diff --git a/src/state/write.ts b/src/state/write.ts
index c11f0e3..2ab74d9 100644
--- a/src/state/write.ts
+++ b/src/state/write.ts
@@ -4,6 +4,19 @@ import { readFileSync, writeFileSync } from 'node:fs';

+// fastPathWrite deliberately contains no logging and no retries.
+export function fastPathWrite(file: string, bytes: Buffer): void {
+  const before = readFileSync(file); // snapshot of the last good state
+  try {
+    writeFileSync(file, bytes);
+  } catch (err) {
+    // A failed apply must not leave a torn file behind: the last good
+    // bytes are put back before the error propagates to the caller.
+    writeFileSync(file, before);
+    throw err;
+  }
+}
